test('mergeCustomers removes fromId customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers keeps intoId customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const intoCustomer = result.value.customers.find((c) => c.id === 'C-002');
  assert.ok(intoCustomer);
  assert.equal(intoCustomer.name, 'Blue Fern Bakery');
});

test('mergeCustomers reassigns invoices from fromId to intoId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-01-20',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued2 = issueInvoice(inv2, [issued1.number]).value;

  const invoices = [issued1, issued2];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers does not mutate input customers', () => {
  const customers = listCustomers();
  const originalLength = customers.length;
  const invoices = [];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalLength);
  assert.ok(customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers does not mutate input invoices', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const invoices = [issued1];
  const originalCustomerId = invoices[0].customerId;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(invoices[0].customerId, originalCustomerId);
});

